query GetAccounts($first: Int, $after: String, $type: AccountType, $archived: Boolean) {
  accounts(first: $first, after: $after, type: $type, archived: $archived) {
    edges {
      node {
        id
        name
        type
        currency
        balanceCurrent
        archived
        createdAt
        updatedAt
        userId
        metadata
      }
      cursor
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    totalCount
  }
}

